# split-source: order=74 original-lines=435-481 hash=521b7ee87110fe55


def _ensure_embedded_liquid_kernel_package(package_root: Path | None = None) -> dict:
    raw_root = Path(package_root or (Path(__file__).resolve().parent / "liquid_kernel"))
    if raw_root.is_symlink() or (raw_root.exists() and not raw_root.is_dir()):
        quarantine = raw_root.with_name(f"{raw_root.name}.invalid-{uuid.uuid4().hex[:12]}")
        raw_root.rename(quarantine)
    root = raw_root.resolve(strict=False)
    required = ("__init__.py", "control.py", "models.py")
    capability = 0
    ready = root.is_dir() and all((root / name).is_file() and not (root / name).is_symlink() for name in required)
    if ready:
        try:
            match = re.search(r"^EVOLUTION_MODEL_CAPABILITY_VERSION = (\d+)$", (root / "control.py").read_text(encoding="utf-8"), re.M)
            capability = int(match.group(1)) if match else 0
            ready = capability >= 2
        except Exception:
            ready = False
    if ready:
        return {"root": str(root), "ready": True, "restored": False, "source": "local",
                "required_files": list(required), "model_capability_version": capability}
    root.mkdir(parents=True, exist_ok=True)
    backup = None
    try:
        payload = base64.b64decode(_EMBEDDED_LIQUID_KERNEL_PACKAGE_B64.encode("ascii"), validate=True)
        with zipfile.ZipFile(io.BytesIO(payload)) as archive:
            names = (*required, "README.md")
            contents = {name: archive.read(name) for name in names}
            # Back up package code only. Runtime records, config, signing keys
            # and artifact/version history stay at their original paths.
            if any((root / name).exists() for name in names):
                backup = root / ".package-backups" / uuid.uuid4().hex
                backup.mkdir(parents=True)
                for name in names:
                    old = root / name
                    if old.is_file():
                        shutil.copy2(old, backup / name)
            for name, content in contents.items():
                target = root / name
                temporary = target.with_name(f".{target.name}.{uuid.uuid4().hex}.tmp")
                temporary.write_bytes(content)
                os.replace(temporary, target)
    except Exception as exc:
        raise RuntimeError(f"unable to restore embedded liquid_kernel package: {type(exc).__name__}") from exc
    return {"root": str(root), "ready": True, "restored": True, "source": "embedded",
            "required_files": list(required), "model_capability_version": 2,
            "backup_root": str(backup) if backup else ""}

# split-source: order=77 original-lines=490-505 hash=861baa5a704fc2e7


def _ensure_liquid_kernel_sqlite_lifecycle(registry_class) -> None:
    """Close legacy local-package connections without replacing customized files."""
    if getattr(registry_class, "SQLITE_CONNECTIONS_CLOSE_ON_EXIT", False):
        return
    original_connect = registry_class._connect

    @contextlib.contextmanager
    def managed_connect(self):
        with contextlib.closing(original_connect(self)) as conn:
            with conn:
                yield conn

    registry_class._connect = managed_connect
    registry_class.SQLITE_CONNECTIONS_CLOSE_ON_EXIT = True

# split-source: order=934 original-lines=14936-14940 hash=5cd9aacc032a0f5b


def _liquid_kernel_history_present(runtime_root: Path) -> bool:
    root = Path(runtime_root)
    return root.is_dir() and any((root / name).exists() for name in ("registry.sqlite", "active.json", "artifacts"))

# split-source: order=935 original-lines=14941-14970 hash=af942e21e79e26a3


def prepare_liquid_kernel_runtime(runtime_root: Path, startup_policy: object = "inherit") -> dict:
    raw_root = Path(runtime_root)
    if raw_root.is_symlink() or (raw_root.exists() and not raw_root.is_dir()):
        quarantine = raw_root.with_name(f"{raw_root.name}.invalid-{uuid.uuid4().hex[:12]}")
        raw_root.rename(quarantine)
    root = raw_root.resolve(strict=False)
    root.parent.mkdir(parents=True, exist_ok=True)
    policy = normalize_liquid_kernel_startup_policy(startup_policy)
    history_present = _liquid_kernel_history_present(root)
    root.mkdir(parents=True, exist_ok=True)
    status = {
        "schema_version": 1,
        "runtime_root": str(root),
        "history_present": bool(history_present),
        "history_action": "inherited" if history_present else "initialized",
        "requested_policy": policy,
        "effective_policy": "inherit",
        "embedded_package": dict(LIQUID_KERNEL_PACKAGE_STATUS),
        "injected_version": "",
        "updated_at": now_ts(),
    }
    state_path = root.parent / LIQUID_KERNEL_BOOTSTRAP_STATE_FILENAME
    _write_json_file(state_path, status)
    try:
        os.chmod(state_path, 0o600)
    except Exception:
        pass
    return status

# split-source: order=936 original-lines=14971-14984 hash=bc332d47a0e9051a


def _persist_liquid_kernel_bootstrap(runtime_root: Path, status: dict) -> dict:
    root = Path(runtime_root).resolve(strict=False)
    state_path = root.parent / LIQUID_KERNEL_BOOTSTRAP_STATE_FILENAME
    payload = {str(key): value for key, value in dict(status or {}).items()}
    payload["runtime_root"] = str(root)
    payload["updated_at"] = now_ts()
    _write_json_file(state_path, payload)
    try:
        os.chmod(state_path, 0o600)
    except Exception:
        pass
    return payload
